import csv, json, difflib
from collections import defaultdict
W=json.load(open('watchlist.json'))
cust={c['customer_id']:c for c in csv.DictReader(open('dev/customers_dev.csv'))}
labs=list(csv.DictReader(open('dev/labels_dev.csv')))
by=defaultdict(list)
for l in labs: by[l['class']].append(l)
names=[(e,n) for e in W for n in [e['primary_name']]+[a['name'] for a in e['aliases']]]
def near(s, k=2):
    sc=sorted(names, key=lambda en: -difflib.SequenceMatcher(None, s.lower(), en[1].lower()).ratio())[:k]
    return sc
for cl in ['D1_name_dob_conflict','D2_near_name','D5_partial_dob_conflict','D6_same_given','D7_id_unlisted','D3_weak_alias_alone','D4_entity_near_name']:
    print('='*20, cl, len(by[cl]))
    for l in by[cl][:10]:
        c=cust[l['customer_id']]
        print(f\"  CUST: {c['full_name']!r} dob={c['dob']} id={c['id_type']}:{c['id_number']}\")
        for e,n in near(c['full_name']):
            print(f\"    NEAR: {n!r} (uid {e[\\\"uid\\\"]}) primary={e['primary_name']!r} dob={e['dob']} ids={e['ids']}\")
