import json, re, sys
from collections import Counter, defaultdict

W = json.load(open('/app/watchlist.json'))
PART = {'bin', 'ibn', 'ben', 'b.', 'al', 'el', 'bint', 'de', 'la', 'du', 'von', 'van', 'da', 'abu'}


def toks(n):
    n = n.replace(',', ' ')
    out = []
    for t in re.split(r'[\s]+', n):
        t = t.strip('.,')
        if not t:
            continue
        out.append(t)
    return out


indiv = [e for e in W if e['type'] == 'individual']
prim = Counter()
for e in indiv:
    for t in toks(e['primary_name']):
        prim[t] += 1

if sys.argv[1] == 'vocab':
    lat = [(k, v) for k, v in prim.most_common() if re.match(r'^[A-Za-z]', k)]
    print(len(lat))
    for k, v in lat:
        print('%-22s %d' % (k, v))
elif sys.argv[1] == 'pairs':
    # align primary tokens with strong-alias tokens
    seen = Counter()
    for e in indiv:
        p = toks(e['primary_name'])
        for a in e['aliases']:
            if a['strength'] != 'strong':
                continue
            q = toks(a['name'])
            pl = [t for t in p if t.lower().strip('-') not in PART]
            ql = [t for t in q if t.lower().strip('-') not in PART]
            pl = [t.split('-')[-1] if t.lower().startswith(('al-', 'el-')) else t for t in pl]
            ql = [t.split('-')[-1] if t.lower().startswith(('al-', 'el-')) else t for t in ql]
            if len(pl) == len(ql):
                for x, y in zip(pl, ql):
                    if x.lower() != y.lower():
                        seen[(x, y)] += 1
    for (x, y), c in seen.most_common():
        print('%-24s %-24s %d' % (x, y, c))
elif sys.argv[1] == 'ent':
    for e in W:
        if e['type'] == sys.argv[2]:
            print(e['primary_name'], '||', [a['name'] for a in e['aliases']])

