input.content:
import json, re, sys
from collections import Counter, defaultdict
W = json.load(open('/app/watchlist.json'))


def toks(n):
    return [t for t in re.split(r'[\s,]+', n.strip()) if t]


mode = sys.argv[1]
if mode == 'align':
    # align Latin primary with script_name token-wise
    pair = Counter()
    bad = 0
    for e in W:
        if e['type'] != 'individual' or not e['script_name']:
            continue
        p, s = toks(e['primary_name']), toks(e['script_name'])
        if re.match(r'^[A-Za-z]', e['primary_name']) is None:
            continue
        if len(p) != len(s):
            bad += 1
            print('LEN', e['primary_name'], '|', e['script_name'])
            continue
        for x, y in zip(p, s):
            pair[(x, y)] += 1
    print('misaligned:', bad, 'pairs:', len(pair))
    for (x, y), c in sorted(pair.items()):
        print('%-20s %-14s %d' % (x, y, c))
elif mode == 'scriptonly':
    n = 0
    for e in W:
        if e['type'] == 'individual' and re.match(r'^[A-Za-z]', e['primary_name']) is None:
            n += 1
    print('script-primary individuals:', n)
elif mode == 'entwords':
    c = Counter()
    first = Counter()
    for e in W:
        if e['type'] != 'entity':
            continue
        t = toks(e['primary_name'])
        first[t[0]] += 1
        for x in t:
            c[x] += 1
    print('FIRST WORDS'); [print('%-24s %d' % kv) for kv in first.most_common()]
    print('ALL WORDS'); [print('%-24s %d' % kv) for kv in c.most_common()]
elif mode == 'vesselwords':
    c = Counter()
    for e in W:
        if e['type'] != 'vessel':
            continue
        for x in toks(e['primary_name']):
            c[x] += 1
    [print('%-24s %d' % kv) for kv in c.most_common()]

