input.content:
import json, re, sys
from collections import Counter, defaultdict
W = json.load(open('/app/watchlist.json'))
ARAB = re.compile(r'[؀-ۿ]')
CYR = re.compile(r'[Ѐ-ӿ]')


def toks(n):
    return [t for t in re.split(r'[\s,]+', n.strip()) if t]


# script tokens seen in any script_name
script_tok = Counter()
for e in W:
    if e['script_name']:
        for t in toks(e['script_name']):
            script_tok[t] += 1
# script tokens with a Latin counterpart via aligned primary
mapped = defaultdict(Counter)
for e in W:
    if not e['script_name'] or not re.match(r'^[A-Za-z]', e['primary_name'] or ''):
        continue
    p, s = toks(e['primary_name']), toks(e['script_name'])
    if len(p) != len(s):
        continue
    for x, y in zip(p, s):
        mapped[y][x.lower()] += 1
print('distinct script tokens:', len(script_tok), 'with latin:', len(mapped))
unmapped = [(t, c) for t, c in script_tok.most_common() if t not in mapped]
print('unmapped:', len(unmapped), sum(c for _, c in unmapped))
for t, c in unmapped[:60]:
