#!/usr/bin/env python3
"""Signature of unmatched individuals: is the given / family name in the pool?"""
import csv, json, sys
from collections import Counter, defaultdict
sys.path.insert(0, '/app')
import screen as S

W = json.load(open('/app/watchlist.json'))
eng = S.Engine(W)
givens = set()
families = set()
for e in W:
    if (e.get('type') or '') != 'individual':
        continue
    for nm in e.get('_names', []):
        givens.update(nm['given_cls'])
        families.update(nm['family_cls'])

path = sys.argv[1]
labels = {}
if len(sys.argv) > 2:
    labels = {l['customer_id']: l for l in csv.DictReader(open(sys.argv[2]))}
rows = list(csv.DictReader(open(path, encoding='utf-8-sig')))
sig = Counter()
bycls = defaultdict(Counter)
examples = defaultdict(list)
for c in rows:
    if c['type'] != 'individual':
        continue
    if eng.screen(c):
        continue
    p = eng.parse_variants(c['full_name'])[0]
    cls, views = eng._views(p)
    if not views or len(views[0]) < 2:
        s = 'short'
    else:
        idx = views[0]
        a = set(x for x, _ in cls[idx[0]])
        b = set(x for x, _ in cls[idx[-1]])
        fwd = bool(a & givens) and bool(b & families)
        bwd = bool(b & givens) and bool(a & families)
        if fwd or bwd:
            s = 'both_in_pool'
        elif (a & givens) or (b & givens) or (a & families) or (b & families):
            s = 'one_in_pool'
        else:
            s = 'none_in_pool'
    sig[s] += 1
    if labels:
        bycls[labels[c['customer_id']]['class']][s] += 1
    if len(examples[s]) < 8:
        examples[s].append(c['full_name'])
print(path, 'unmatched individuals:', sum(sig.values()))
for k, v in sig.most_common():
    print('  %-14s %5d  e.g. %s' % (k, v, examples[k][:4]))
if labels:
    print()
    for cl in sorted(bycls):
        print('  %-28s %s' % (cl, dict(bycls[cl])))

