#!/usr/bin/env python3
"""Unmatched individuals whose family matches an entry and whose given name is
phonetically close to that entry's given name -> candidate misses."""
import csv, json, sys
sys.path.insert(0, '/app')
import screen as S

W = json.load(open('/app/watchlist.json'))
eng = S.Engine(W)
path = sys.argv[1]
lim = float(sys.argv[2]) if len(sys.argv) > 2 else 1.6
show = int(sys.argv[3]) if len(sys.argv) > 3 else 40

fam_index = {}
for e in W:
    if (e.get('type') or '') != 'individual':
        continue
    for nm in e.get('_names', []):
        for f in nm['family_cls']:
            fam_index.setdefault(f, []).append((e, nm))

rows = list(csv.DictReader(open(path, encoding='utf-8-sig')))
hits = []
for c in rows:
    if c['type'] != 'individual':
        continue
    if eng.screen(c):
        continue
    p = eng.parse_variants(c['full_name'])[0]
    cls, views = eng._views(p)
    if not views or len(views[0]) < 2:
        continue
    idx = views[0]
    for gi, fi in ((idx[0], idx[-1]), (idx[-1], idx[0])):
        gskel = S.skeleton(p.core_all[gi][0] if p.core_all[gi][1] == 'latin'
                           else S.to_latin(p.core_all[gi][0]))
        for f, _ in cls[fi]:
            for e, nm in fam_index.get(f, ()):
                if S.dob_compare(c['dob'], e.get('dob') or '') == 'conflict':
                    continue
                for g in nm['given_cls']:
                    d = S.pdist(gskel, S.skeleton(g), 9.0)
                    if d < lim:
                        hits.append((d, c['full_name'], c['dob'], nm['raw'],
                                     e['uid'], e['dob'], g))
hits.sort()
seen = set()
n = 0
for d, name, dob, raw, uid, edob, g in hits:
    if name in seen:
        continue
    seen.add(name)
    n += 1
    print('%.2f  %-40r dob=%-10s  vs %-38r uid=%s dob=%-10s given=%s'
          % (d, name, dob, raw, uid, edob, g))
    if n >= show:
        break
print('total candidate misses:', len(seen))

