#!/usr/bin/env python3
"""Stress test: synthesise customers from watchlist entries under various
romanisation conventions and measure recall per convention."""
import json, random, re, sys
from collections import Counter, defaultdict
sys.path.insert(0, '/app')
import screen as S
import styles

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 7)
W = json.load(open('/app/watchlist.json'))
eng = S.Engine(W)

# nationality hints -> which style family
AR_NAT = {'EG', 'SA', 'AE', 'LB', 'SY', 'IQ', 'JO', 'YE', 'KW', 'QA', 'OM',
          'BH', 'LY', 'MA', 'TN', 'DZ', 'SD', 'IR', 'AF', 'PK', 'TR', 'ID'}
RU_NAT = {'RU', 'BY', 'UA', 'KZ', 'UZ', 'AM', 'GE', 'MD', 'AZ', 'KG', 'TJ'}


def token_style(tok, fn):
    out = fn(tok.lower())
    return out


def build_variant(entry, style_name, fn):
    """Return a customer full_name spelled in the given style."""
    p = eng.parse(entry['primary_name'])
    if not p.core or len(p.core) < 2:
        return None
    if any(sc != 'latin' for _, sc in p.core):
        return None
    toks = [b for b, _ in p.core]
    new = [token_style(t, fn) for t in toks]
    # reinstate arabic article / structure variation
    r = random.random()
    if r < 0.25:
        name = ', '.join([new[-1], ' '.join(new[:-1])])
    elif r < 0.4:
        name = ' '.join([new[-1]] + new[:-1])
    else:
        name = ' '.join(new)
    return name


def main():
    ok = Counter()
    tot = Counter()
    fails = defaultdict(list)
    persons = [e for e in W if e['type'] == 'individual'
               and S.script_of(e['primary_name']) == 'latin']
    for e in persons:
        nats = set(e.get('nationalities') or [])
        script = e.get('script_name') or ''
        sc = S.script_of(script) if script else 'latin'
        if sc == 'arab':
            fam = styles.AR_STYLES
        elif sc == 'cyr':
            fam = styles.RU_STYLES
        else:
            continue
        for sname, fn in fam.items():
            nm = build_variant(e, sname, fn)
            if not nm:
                continue
            cust = {'customer_id': 'X', 'full_name': nm,
                    'dob': e.get('dob') or '', 'nationality': '',
                    'id_type': '', 'id_number': '', 'type': 'individual'}
            got = eng.screen(cust)
            tot[sname] += 1
            if got == e['uid']:
                ok[sname] += 1
            else:
                fails[sname].append((nm, e['uid'], e['primary_name'], got))
    print('%-14s %6s %6s %s' % ('style', 'n', 'ok', 'recall'))
    for s in sorted(tot):
        print('%-14s %6d %6d %.3f' % (s, tot[s], ok[s], ok[s] / tot[s]))
    print()
    for s in sorted(fails):
        print('=' * 8, s, len(fails[s]))
        for nm, uid, pn, got in fails[s][:12]:
            print('   %-42r -> %-34r  got=%s' % (nm, pn, got))


main()

