        return None
    if any(sc != 'latin' for _, sc in p.core):
        return None
    toks = [b for b, _ in p.core]
    new = [token_style(t, fn) for t in toks]
    # reinstate arabic article / structure variation
    r = random.random()
    if r < 0.25:
        name = ', '.join([new[-1], ' '.join(new[:-1])])
    elif r < 0.4:
        name = ' '.join([new[-1]] + new[:-1])
    else:
        name = ' '.join(new)
    return name


def main():
    ok = Counter()
    tot = Counter()
    fails = defaultdict(list)
    persons = [e for e in W if e['type'] == 'individual'
               and S.script_of(e['primary_name']) == 'latin']
    for e in persons:
        nats = set(e.get('nationalities') or [])
        script = e.get('script_name') or ''
        sc = S.script_of(script) if script else 'latin'
        if sc == 'arab':
            fam = styles.AR_STYLES
        elif sc == 'cyr':
            fam = styles.RU_STYLES
        else:
            continue
        for sname, fn in fam.items():
            nm = build_variant(e, sname, fn)
            if not nm:
                continue
            cust = {'customer_id': 'X', 'full_name': nm,
                    'dob': e.get('dob') or '', 'nationality': '',
                    'id_type': '', 'id_number': '', 'type': 'individual'}
            got = eng.screen(cust)
            tot[sname] += 1
            if got == e['uid']:
                ok[sname] += 1
            else:
                fails[sname].append((nm, e['uid'], e['primary_name'], got))
    print('%-14s %6s %6s %s' % ('style', 'n', 'ok', 'recall'))
    for s in sorted(tot):
        print('%-14s %6d %6d %.3f' % (s, tot[s], ok[s], ok[s] / tot[s]))
    print()
    for s in sorted(fails):
        print('=' * 8, s, len(fails[s]))
        for nm, uid, pn, got in fails[s][:12]:
            print('   %-42r -> %-34r  got=%s' % (nm, pn, got))


main()

