"""Entity / vessel stress: legal-form swaps, vessel prefixes, decoys."""
import json, random, sys
from collections import Counter, defaultdict
sys.path.insert(0, '/app')
import screen as S

random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 3)
W = json.load(open('/app/watchlist.json'))
eng = S.Engine(W)

FORMS = ['LLC', 'L.L.C.', 'Limited Liability Company', 'Ltd', 'Ltd.',
         'Limited', 'Inc', 'Inc.', 'Incorporated', 'Corp', 'Corp.',
         'Corporation', 'Co', 'Co.', 'Company', 'SA', 'S.A.',
         'Sociedad Anonima', 'GmbH', 'G.m.b.H.', 'JSC', 'Joint Stock Company',
         'AO', 'OAO', 'PJSC', 'Public Joint Stock Company', 'FZE', 'FZ-LLC',
         'Free Zone Establishment', '']
PREFIXES = ['M/V ', 'MV ', 'M/T ', 'MT ', 'M/S ', 'MS ', 'SS ', 'Vessel ', '']

ok = Counter()
bad = []
for e in W:
    t = e['type']
    if t == 'entity':
        core = S.org_words(e['primary_name'])
        if not core:
            continue
        for _ in range(3):
            nm = ' '.join(core) + ' ' + random.choice(FORMS)
            if random.random() < 0.2:
                nm = 'The ' + nm
            if random.random() < 0.2:
                nm = nm.replace(' ', ', ', 1)
            cust = {'customer_id': 'X', 'full_name': nm.strip(), 'dob': '',
                    'nationality': '', 'id_type': '', 'id_number': '',
                    'type': 'entity'}
            got = eng.screen(cust)
            if got == e['uid']:
                ok['ent_ok'] += 1
            else:
                # another entry with the same normalised name is fine
                if got and S.org_key(nm) in [S.org_key(x['primary_name'])
                                             for x in W if x['uid'] == got]:
                    ok['ent_ok'] += 1
                else:
                    ok['ent_bad'] += 1
                    bad.append((nm, e['primary_name'], e['uid'], got))
    elif t == 'vessel':
        core = S.org_words(e['primary_name'])
        if not core:
            continue
        for _ in range(3):
            nm = random.choice(PREFIXES) + ' '.join(core)
            cust = {'customer_id': 'X', 'full_name': nm.strip(), 'dob': '',
                    'nationality': '', 'id_type': '', 'id_number': '',
                    'type': 'vessel'}
            got = eng.screen(cust)
            if got == e['uid']:
                ok['ves_ok'] += 1
            else:
                names = [x['primary_name'] for x in W if x['uid'] == got]
                if got and names and S.org_key(names[0]) == S.org_key(nm):
                    ok['ves_ok'] += 1
                else:
                    ok['ves_bad'] += 1
                    bad.append((nm, e['primary_name'], e['uid'], got))

# decoys: swap one content word
words_by_pos = defaultdict(set)
for e in W:
    if e['type'] in ('entity', 'vessel'):
        w = S.org_words(e['primary_name'])
        for i, x in enumerate(w):
            words_by_pos[(e['type'], min(i, 2))].add(x)
real = set()
for e in W:
    if e['type'] in ('entity', 'vessel'):
        real.add((e['type'], S.org_key(e['primary_name'])))
        for a in e['aliases']:
            if a['strength'] == 'strong':
                real.add((e['type'], S.org_key(a['name'])))
fp = 0
tot = 0
for e in W:
    t = e['type']
    if t not in ('entity', 'vessel'):
        continue
    core = S.org_words(e['primary_name'])
    if len(core) < 2:
        continue
    for i in range(len(core)):
        alt = list(core)
        pool = [x for x in words_by_pos[(t, min(i, 2))] if x != core[i]]
        if not pool:
            continue
        alt[i] = random.choice(pool)
        key = (t, ' '.join(alt))
        if key in real:
            continue
        nm = ' '.join(alt) + (' Ltd' if t == 'entity' else '')
        cust = {'customer_id': 'X', 'full_name': nm, 'dob': '',
                'nationality': '', 'id_type': '', 'id_number': '',
                'type': t}
        tot += 1
        got = eng.screen(cust)
        if got:
            fp += 1
            if fp < 12:
                print('   FP %-40r -> %r' % (
                    nm, {x['uid']: x for x in W}[got]['primary_name']))
print(dict(ok))
print('decoys %d  fp %d  rate %.4f' % (tot, fp, fp / tot))
for nm, src, uid, got in bad[:15]:
    print('   %-44r want %-34r got %s' % (nm, src, got))

